do $$
begin
  if exists (
    select 1 from enterprise_identity_connections
    where status='ACTIVE'
    group by provider_id, issuer_uri, api_audience
    having count(*) > 1
  ) then
    raise exception 'Cannot restore legacy ACTIVE binding uniqueness while shared-issuer bindings exist';
  end if;
end $$;
create unique index uq_eic_active_binding
on enterprise_identity_connections(provider_id, issuer_uri, api_audience)
where status='ACTIVE';
